/** @module menquery */
import _ from 'lodash'
import MenqueryParam from './menquery-param'
import MenquerySchema from './menquery-schema'

/**
 * Validator object.
 * @typedef {Object} Validator
 * @property {boolean} valid - Indicates if the value is valid or not.
 * @property {string} message - The error message.
 * @property {string} [param] - The name of the param.
 * @property {*} [value] - The value of the param.
 */
/**
 * Param parser callback.
 * @callback parserFn
 * @param {*} parserValue - The value passed to the parser.
 * @param {*} paramValue - The value passed to the param.
 * @param {MenqueryParam} param - The `MenqueryParam` object.
 * @return {*} The parsed value
 */
/**
 * Param formatter callback.
 * @callback formatterFn
 * @param {*} formatterValue - The value passed to the formatter.
 * @param {*} paramValue - The value passed to the param.
 * @param {MenqueryParam} param - The `MenqueryParam` object.
 * @return {*} The formatted value
 */
/**
 * Param validator callback.
 * @callback validatorFn
 * @param {*} validatorValue - The value passed to the validator.
 * @param {*} paramValue - The value passed to the param.
 * @param {MenqueryParam} param - The `MenqueryParam` object.
 * @return {Validator}
 */

let handlers = {
  parsers: {},
  formatters: {},
  validators: {}
}

export {MenqueryParam as Param}
export {MenquerySchema as Schema}

/**
 * Get or set a handler.
 * @param {string} type - Handler type.
 * @param {string} name - Handler name.
 * @param {Function} [fn] - Set the handler method.
 */
export function handler (type, name, fn) {
  if (arguments.length > 2) {
    handlers[type][name] = fn
  }

  return handlers[type][name]
}

/**
 * Get or set a parser.
 * @param {string} name - Parser name.
 * @param {parserFn} [fn] - Set the parser method.
 * @return {parserFn} The parser method.
 */
export function parser (name, fn) {
  return handler('parsers', ...arguments)
}

/**
 * Get or set a formatter.
 * @param {string} name - Formatter name.
 * @param {formatterFn} [fn] - Set the formatter method.
 * @return {formatterFn} The formatter method.
 */
export function formatter (name, fn) {
  return handler('formatters', ...arguments)
}

/**
 * Get or set a validator.
 * @param {string} name - Validator name.
 * @param {validatorFn} [fn] - Set the validator method.
 * @return {validatorFn} The validator method.
 */
export function validator (name, fn) {
  return handler('validators', ...arguments)
}

/**
 * Create a middleware.
 * @param {MenquerySchema|Object} [schema] - Schema object.
 * @param {Object} [options] - Options to be passed to schema.
 * @return {Function} The middleware.
 */
export function middleware (schema, options) {
  return function (req, res, next) {
    let _schema = schema instanceof MenquerySchema
                ? _.clone(schema)
                : new MenquerySchema(schema, options)

    _.forIn(handlers, (typedHandler, type) => {
      _.forIn(typedHandler, (handler, name) => {
        _schema.handler(type, name, handler)
      })
    })

    _schema.validate(req.query, (err) => {
      if (err) {
        res.status(400)
        return next(err)
      }

      req = _.merge(req, _schema.parse())
      next()
    })
  }
}

export default middleware

import _ from 'lodash'

export default class MenqueryParam {

  /**
   * Create a param.
   * @param {string} name - Param name.
   * @param {*} [value] - The value of the param.
   * @param {Object} [options] - Options of the param.
   */
  constructor (name, value, options) {
    this.name = name
    this.handlers = {
      parsers: {},
      formatters: {},
      validators: {}
    }
    this.options = _.assign({
      type: String,
      paths: [name],
      bindTo: 'filter',
      multiple: false,
      separator: ',',
      operator: '$eq',
      trim: true,
      set: (value, param) => value,
      get: (value, param) => value
    }, options)

    this.formatter('default', (defaultValue, value, param) => {
      if (_.isNil(value) || _.isNaN(value) || value === '') {
        return _.isFunction(defaultValue) ? defaultValue(this) : defaultValue
      }
      return value
    })

    this.formatter('normalize', (normalize, value, param) => {
      if (normalize && !_.isNil(value)) {
        value = _.kebabCase(value).replace(/\-/g, ' ')
      }
      return value
    })

    this.formatter('lowercase', (lowercase, value, param) => {
      if (lowercase && !_.isNil(value)) {
        value = _.toLower(value)
      }
      return value
    })

    this.formatter('uppercase', (uppercase, value, param) => {
      if (uppercase && !_.isNil(value)) {
        value = _.toUpper(value)
      }
      return value
    })

    this.formatter('trim', (trim, value, param) => {
      if (trim && !_.isNil(value)) {
        value = _.trim(value)
      }
      return value
    })

    this.validator('required', (required, value, param) => ({
      valid: !required || !_.isNil(value) && !_.isNaN(value) && value !== '',
      message: `${param.name} is required`
    }))

    this.validator('min', (min, value, param) => ({
      valid: !_.isNumber(min) || _.isNil(value) || value >= min,
      message: `${param.name} must be greater than or equal to ${min}`
    }))

    this.validator('max', (max, value, param) => ({
      valid: !_.isNumber(max) || _.isNil(value) || value <= max,
      message: `${param.name} must be lower than or equal to ${max}`
    }))

    this.validator('minlength', (minlength, value, param) => ({
      valid: !_.isNumber(minlength) || _.isNil(value) || value.length >= minlength,
      message: `${param.name} must have length greater than or equal to ${minlength}`
    }))

    this.validator('maxlength', (maxlength, value, param) => ({
      valid: !_.isNumber(maxlength) || _.isNil(value) || value.length <= maxlength,
      message: `${param.name} must have length lower than or equal to ${maxlength}`
    }))

    this.validator('enum', (_enum, value, param) => ({
      valid: !_.isArray(_enum) || _.isNil(value) || ~_enum.indexOf(value),
      message: `${param.name} must be one of: ${_enum.join(', ')}`
    }))

    this.validator('match', (match, value, param) => ({
      valid: !_.isRegExp(match) || _.isNil(value) || match.test(value),
      message: `${param.name} must match regular expression ${match}`
    }))

    this.value(value)
  }

  /**
   * Get or set an option.
   * @param {string} name - Option name.
   * @param {*} [value] - Set the value of the option.
   * @return {*} Value of the option.
   */
  option (name, value) {
    if (arguments.length > 1) {
      this.options[name] = value
    }

    return this.options[name]
  }

  /**
   * Get or set a handler.
   * @param {string} type - Handler type.
   * @param {string} name - Handler name.
   * @param {Function} [fn] - Set the handler method.
   */
  handler (type, name, fn) {
    if (arguments.length > 2) {
      this.handlers[type][name] = fn
    }

    return this.handlers[type][name]
  }

  /**
   * Get or set a parser.
   * @param {string} name - Parser name.
   * @param {parserFn} [fn] - Set the parser method.
   * @return {parserFn} The parser method.
   */
  parser (name, fn) {
    return this.handler('parsers', ...arguments)
  }

  /**
   * Get or set a formatter.
   * @param {string} name - Formatter name.
   * @param {formatterFn} [fn] - Set the formatter method.
   * @return {formatterFn} The formatter method.
   */
  formatter (name, fn) {
    return this.handler('formatters', ...arguments)
  }

  /**
   * Get or set a validator.
   * @param {string} name - Validator name.
   * @param {validatorFn} [fn] - Set the validator method.
   * @return {validatorFn} The validator method.
   */
  validator (name, fn) {
    return this.handler('validators', ...arguments)
  }

  /**
   * Parse the param.
   * @param {*} [value] - Set the param value.
   * @param {string|string[]} path - Set the param path/paths.
   * @return {Object} The parsed value.
   */
  parse (value = this._value, path = this.options.paths) {
    let operator = this.options.operator
    let query = {}

    if (_.isNil(value)) {
      return query
    } else if (value !== this._value) {
      value = this.value(value)
    }

    if (_.isArray(path)) {
      let paths = path
      if (paths.length > 1) {
        query.$or = paths.map((path) => this.parse(value, path))
        return query
      }
      path = paths[0]
    }

    if (_.isArray(value)) {
      operator = operator === '$ne' ? '$nin' : '$in'
    }

    _.forIn(this.options, (optionValue, option) => {
      let parser = this.handlers.parsers[option]
      if (_.isFunction(parser)) {
        if (_.isArray(value)) {
          value = value.map((v) => parser(optionValue, v))
        } else {
          value = parser(optionValue, value)
        }
      }
    })

    if (operator === '$eq' || _.isRegExp(value)) {
      query[path] = value
    } else {
      query[path] = {[operator]: value}
    }

    return query
  }

  /**
   * Get or set the param value.
   * @param {*} [value] - Set the param value.
   * @param {boolean} [bind=true] - Set if value must be bound to parameter or not.
   * @return {*} The formatted value.
   */
  value (value, bind = true) {
    let options = this.options

    if (arguments.length === 0) {
      if (_.isArray(this._value)) {
        return this._value.map((v) => options.get(v))
      } else {
        return options.get(this._value, this)
      }
    }

    if (options.multiple) {
      let values = value

      if (_.isString(value) && ~value.search(options.separator)) {
        values = value.split(options.separator)
      }

      if (_.isArray(values)) {
        values = values.map((value) => this.value(value, false))

        if (bind) {
          this._value = values
        }

        return values
      }
    }

    _.forIn(this.options, (optionValue, option) => {
      let formatter = this.handlers.formatters[option]
      if (_.isFunction(formatter)) {
        value = formatter(optionValue, value)
      }
    })

    if (!_.isNil(value)) {
      if (options.type.name === 'RegExp') {
        value = new RegExp(value, 'i')
      } else if (options.type.name === 'Date') {
        value = new Date(value)
      } else {
        value = options.type(value)
      }
    }

    value = options.set(value, this)

    if (bind) {
      this._value = value
    }

    return value
  }

  /**
   * Validates the param.
   * @param {*} [value] - Set the param value.
   * @param {Function} [next] - Callback to be called with error
   * @return {boolean} Result of the validation.
   */
  validate (value = this._value, next = (error) => !error) {
    let error

    if (_.isFunction(value)) {
      next = value
      value = this._value
    }

    if (_.isArray(value)) {
      for (let i = 0; i < value.length; i++) {
        if (error) break
        this.validate(value[i], (err) => { error = err })
      }

      return next(error)
    }

    for (let option in this.options) {
      let validator = this.handlers.validators[option]
      if (error) break
      if (!_.isFunction(validator)) continue
      let optionValue = this.options[option]
      let validation = validator(optionValue, value, this)

      if (!validation.valid) {
        error = _.assign({
          name: option,
          param: this.name,
          value: value,
          [option]: optionValue
        }, validation)
      }
    }

    return next(error)
  }
}

import _ from 'lodash'
import MenqueryParam from './menquery-param'

export default class MenquerySchema {

  /**
   * Create a schema.
   * @param {Object} [params] - Params object.
   * @param {Object} [options] - Options object.
   */
  constructor (params = {}, options = {}) {
    this.options = options
    this.params = {}
    this.handlers = {
      parsers: {},
      formatters: {},
      validators: {}
    }
    this._params = {
      q: {
        type: RegExp,
        normalize: true,
        paths: ['_q']
      },
      page: {
        type: Number,
        default: 1,
        max: 30,
        min: 1,
        bindTo: 'options'
      },
      limit: {
        type: Number,
        default: 30,
        max: 100,
        min: 1,
        bindTo: 'options'
      },
      sort: {
        type: String,
        default: 'name',
        multiple: true,
        bindTo: 'options'
      }
    }

    let keys = _.union(_.keys(this._params), _.keys(params))

    keys.forEach((key) => this.add(key, null, params[key]))
  }

  /**
   * Get or set an option.
   * @param {string} name - Option name.
   * @param {*} [value] - Set the value of the option.
   * @return {*} Value of the option.
   */
  option (name, value) {
    if (arguments.length > 1) {
      this.options[name] = value
    }

    return this.options[name]
  }

  /**
   * Get or set a handler.
   * @param {string} type - Handler type.
   * @param {string} name - Handler name.
   * @param {Function} [fn] - Set the handler method.
   */
  handler (type, name, fn) {
    if (arguments.length > 2) {
      this.handlers[type][name] = fn
      this._refreshHandlersInParams({[type]: {[name]: fn}}, this.params)
    }

    return this.handlers[type][name]
  }

  /**
   * Get or set a parser.
   * @param {string} name - Parser name.
   * @param {parserFn} [fn] - Set the parser method.
   * @return {parserFn} The parser method.
   */
  parser (name, fn) {
    return this.handler('parsers', ...arguments)
  }

  /**
   * Get or set a formatter.
   * @param {string} name - Formatter name.
   * @param {formatterFn} [fn] - Set the formatter method.
   * @return {formatterFn} The formatter method.
   */
  formatter (name, fn) {
    return this.handler('formatters', ...arguments)
  }

  /**
   * Get or set a validator.
   * @param {string} name - Validator name.
   * @param {validatorFn} [fn] - Set the validator method.
   * @return {validatorFn} The validator method.
   */
  validator (name, fn) {
    return this.handler('validators', ...arguments)
  }

  /**
   * Get a param
   * @param {string} name - Param name.
   * @return {MenqueryParam|undefined} The param or undefined if it doesn't exist.
   */
  get (name) {
    name = this._getSchemaParamName(name)

    return this.params[name]
  }

  /**
   * Set param value.
   * @param {string} name - Param name.
   * @param {*} value - Param value.
   * @param {Object} [options] - Param options.
   * @return {MenqueryParam|undefined} The param or undefined if it doesn't exist.
   */
  set (name, value, options) {
    name = this._getSchemaParamName(name)

    if (this.params[name]) {
      let param = this.params[name]

      param.value(value)

      _.forIn(options, (optionValue, option) => {
        param.option(option, optionValue)
      })

      return param
    } else {
      return
    }
  }

  /**
   * Add param.
   * @param {string} name - Param name.
   * @param {*} [value] - Param value.
   * @param {Object} [options] - Param options.
   * @return {MenqueryParam|boolean} The param or false if param is set to false in schema options.
   */
  add (name, value, options) {
    if (name instanceof MenqueryParam) {
      options = name.options
      value = name.value()
      name = name.name
    }

    name = this._getSchemaParamName(name)

    if (this.options[name] === false) {
      return false
    }

    if (_.isString(options)) {
      options = {default: options}
    } else if (_.isNumber(options)) {
      options = {type: Number, default: options}
    } else if (_.isDate(options)) {
      options = {type: Date, default: options}
    } else if (_.isRegExp(options)) {
      options = {type: RegExp, default: options}
    } else if (_.isFunction(options)) {
      options = {type: options}
    }

    options = _.assign(this._params[name], options)
    this.params[name] = new MenqueryParam(name, value, options)

    this._refreshHandlersInParams(this.handlers, {[name]: this.params[name]})

    return this.params[name]
  }

  /**
   * Get, set or add param.
   * @param {string} name - Param name.
   * @param {*} [value] - Param value.
   * @param {Object} [options] - Param options.
   * @return {MenqueryParam|undefined} The param or undefined if it doesn't exist.
   */
  param (name, value, options) {
    if (arguments.length === 1) {
      return this.get(name)
    }

    return this.set(name, value, options) || this.add(name, value, options)
  }

  /**
   * Parse values of the schema params.
   * @param {Object} [values] - Object with {param: value} pairs to parse.
   * @return {Object} Parsed object.
   */
  parse (values = {}) {
    let query = {}

    _.forIn(this.params, (param) => {
      let value = values[this._getQueryParamName(param.name)]

      if (!_.isNil(value)) {
        param.value(value)
      }
    })

    _.forIn(this.params, (param) => {
      let value = param.value()
      let bind = param.options.bindTo

      query[bind] = query[bind] || {}

      if (param.name === 'sort') {
        let fields = _.isArray(value) ? value : [value]
        query[bind].sort = {}
        for (let i = 0; i < fields.length; i++) {
          let field = fields[i]
          if (field.charAt(0) === '-') {
            query[bind].sort[field.slice(1)] = -1
          } else if (field.charAt(0) === '+') {
            query[bind].sort[field.slice(1)] = 1
          } else {
            query[bind].sort[field] = 1
          }
        }
      } else if (param.name === 'limit') {
        query[bind].limit = value
      } else if (param.name === 'page') {
        query[bind].skip = this.params.limit.value() * (value - 1)
      } else {
        query[bind] = _.assign(query[bind], param.parse())
      }
    })

    return query
  }

  /**
   * Validate values of the schema params.
   * @param {Object} [values] - Object with {param: value} pairs to validate.
   * @param {Function} [next] - Callback to be called with error
   * @return {boolean} Result of the validation.
   */
  validate (values = {}, next = (error) => !error) {
    let error

    if (_.isFunction(values)) {
      next = values
      values = {}
    }

    _.forIn(this.params, (param) => {
      let value = values[this._getQueryParamName(param.name)]

      if (!_.isNil(value)) {
        param.value(value)
      }
    })

    for (let i in this.params) {
      if (error) break
      let param = this.params[i]
      param.validate((err) => { error = err })
    }

    return next(error)
  }

  _refreshHandlersInParams (handlers = this.handlers, params = this.params) {
    _.forIn(handlers, (typedHandler, type) => {
      _.forIn(typedHandler, (handler, name) => {
        _.forIn(params, (param) => {
          param.handler(type, name, handler)
        })
      })
    })
  }

  _getSchemaParamName (paramName) {
    return _.findKey(this.options, (option) => option === paramName) || paramName
  }

  _getQueryParamName (paramName) {
    return this.options[paramName] || paramName
  }

}

import request from 'supertest'
import express from 'express'
import test from 'tape'
import _ from 'lodash'
import * as menquery from '../src'
import './menquery-param'
import './menquery-schema'

test('Menquery handler', (t) => {
  t.notOk(menquery.parser('testParser'), 'should not get nonexistent parser')
  t.notOk(menquery.formatter('testFormatter'), 'should not get nonexistent formatter')
  t.notOk(menquery.validator('testValidator'), 'should not get nonexistent validator')

  menquery.parser('testParser', () => 'test')
  menquery.formatter('testFormatter', () => 'test')
  menquery.validator('testValidator', () => ({valid: false}))

  t.ok(menquery.parser('testParser'), 'should get parser')
  t.ok(menquery.formatter('testFormatter'), 'should get formatter')
  t.ok(menquery.validator('testValidator'), 'should get validator')

  t.end()
})

test('Menquery middleware', (t) => {
  let app = express()

  app.get('/posts', menquery.middleware(), (err, req, res, next) => {
    if (err) {
      return res.json(err)
    }
    next()
  }, (req, res) => {
    res.status(200).json(_.pick(req, ['filter', 'options', 'test']))
  })

  request(app)
    .get('/posts')
    .query({page: 50})
    .expect(400)
    .end((err, res) => {
      if (err) throw err
      t.equal(res.body.param, 'page', 'should respond with error')
    })

  request(app)
    .get('/posts')
    .query({limit: 20})
    .expect(200)
    .end((err, res) => {
      if (err) throw err
      t.equal(res.body.options.limit, 20, 'should respond with limit')
    })

  t.end()
})

